 preservationBaselineV1='Research/Gate12R_PreWrite_Preservation_Baseline.v1.json';preservationBaselineV2='Research/Gate12R_PreWrite_Preservation_Baseline.v2.json';compatibilityDiagnosis='Research/Gate12R_Development_Static_Smoke_Failure_Diagnosis.v1.md';provenanceV1='Research/Gate12R_5pct_ProcessReuse_Pilot_Provenance.v1.json';developmentFailureReceipt='Research/Verification/Gate12R_ProcessReuse_5pct/development-static-smoke-v1/failure-receipt.json';developmentFailureManifest='Research/Verification/Gate12R_ProcessReuse_5pct/development-static-smoke-v1/partial-output-manifest.json';developmentFailureCheckpoint='Research/Verification/Gate12R_ProcessReuse_5pct/development-static-smoke-v1/checkpoint.json'
 gate10PassedCheckpoint='Research/Gate10R_Attempt4_Passed_Checkpoint.md';gate11PassedCheckpoint='Research/Gate11R_Attempt2_Passed_Checkpoint.md';gate11CanonicalBaseline='Research/Gate11R_Attempt2_Canonical_Preservation_Baseline.v2.json';gate11CanonicalPs51='Research/Verification/Gate11R_5pct_PreImplementation/v2/canonical-tree-identity.powershell51.v2.json';gate11CanonicalPs7='Research/Verification/Gate11R_5pct_PreImplementation/v2/canonical-tree-identity.powershell7.v2.json'
 gate11BundleManifest='Research/FormalScenarios/Gate11R_5pct/v1/bundle-manifest.json';gate11Matrix='Research/FormalScenarios/Gate11R_5pct/v1/formal-scenario-matrix.json';gate11Preregistration='Research/FormalScenarios/Gate11R_5pct/v1/preregistered-analysis.json';campaignCatalog='Research/PlayableExperiments/Gate11R_5pct/v1/campaign-profile-catalog.json';presetCatalog='Research/PlayableExperiments/Gate11R_5pct/v1/algorithm-preset-catalog.json';sceneCatalog='Research/PlayableExperiments/Gate11R_5pct/v1/playable-scene-catalog.json';coverageManifest='Research/PlayableExperiments/Gate11R_5pct/v1/coverage-manifest.json'
 gate10Module='Research/Gate10RProcessReusePreparation.psm1';lockHygieneModule='Research/Gate10RLockHygieneV3.psm1';unityCommand='Assets/_Scripts/Research/Editor/Gate10RProcessReuseBatchCommand.cs';retainedHarness='Research/Verification/Gate10RAttempt4RetainedHarnessV4.ps1';retainedFrozenSource='Research/Verification/Run-Gate12AnalysisUnitTests.ps1';retainedFrozenSummary='Research/Verification/Gate12_AnalysisUnitTests.summary.json'
 gate12Module='Research/Gate12RProcessReusePreparation.psm1';blockRunner='Research/Run-Gate12RProcessReuseBlock.ps1';telemetryRunner='Research/Run-Gate12RTelemetryProbe.ps1';coldRunner='Research/Run-Gate12RColdReference.ps1';analyzer='Research/Analyze-Gate12RPilot.ps1';pilotRunner='Research/Run-Gate12RPilot.ps1';compileGate='Research/Verification/Run-Gate12RCompile.ps1';staticUnitGateV1='Research/Verification/Run-Gate12RStaticUnitAudit.ps1';staticUnitGateV2='Research/Verification/Run-Gate12RStaticUnitAuditV2.ps1';blockRegressionGate='Research/Verification/Run-Gate12RBlockAndRegressionGates.ps1';validationOnlyAudit='Research/Verification/Run-Gate12RValidationOnlyPrePilotAudit.ps1';postPilotAudit='Research/Verification/Run-Gate12RPostPilotReadinessAudit.ps1';prePilotAttemptV1='Research/Verification/Run-Gate12RPrePilotAttempt.ps1';prePilotAttemptV2='Research/Verification/Run-Gate12RPrePilotAttemptV2.ps1';provenanceGeneratorV1='Research/New-Gate12RProvenance.ps1';provenanceGeneratorV2='Research/New-Gate12RProvenanceV2.ps1'
}
$bound=New-Object Collections.Generic.List[object];foreach($property in $sources.GetEnumerator()){$path=Join-Path $ProjectPath ([string]$property.Value).Replace('/','\');if(-not(Test-Path $path -PathType Leaf)){throw "Missing v2 provenance input: $($property.Value)"};$item=Get-Item $path;$bound.Add([pscustomobject][ordered]@{id=[string]$property.Key;relativePath=[string]$property.Value;rawBytes=[long]$item.Length;sha256=Get-Gate12RLowerSha256 $path})}
function Select-Binding([string]$Id){return @($bound|Where-Object id -eq $Id)[0]}
